import java.io.*; import java.util.*; public class TestClass { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line1 = br.readLine(); if (line1 == null) return; int N = Integer.parseInt(line1.trim()); String[] arr_wealth = br.readLine().split("\\s+"); long[] wealth = new long[N]; for(int i_wealth = 0; i_wealth < N; i_wealth++) { wealth[i_wealth] = Long.parseLong(arr_wealth[i_wealth]); } long out_ = solve(N, wealth); System.out.println(out_); br.close(); } static long solve(int N, long[] wealth) { Map<Long, Integer> freqMap = new HashMap<Long, Integer>(); long[] powersOf3 = new long[42]; long p = 1; for (int i = 1; i <= 41; i++) { p *= 3; powersOf3[i] = p; } long count = 0; for (long w : wealth) { for (int i = 1; i <= 41; i++) { long target = powersOf3[i] - w; if (target <= 0) continue; if (freqMap.containsKey(target)) { count += freqMap.get(target); } } freqMap.put(w, freqMap.getOrDefault(w, 0) + 1); } return count; } }